<template><dialog ref="dialog" class="bio-nexus-dialog exam-state-dialog" @cancel.prevent="close"><form class="dialog-shell" @submit.prevent="confirm"><header class="dialog-header"><div><p>Estado del registro</p><h3>{{ target?.annulled ? "Activar" : "Inactivar" }} {{ entityLabel }}</h3></div><BioNexusDialogCloseButton @click="close" /></header><section class="dialog-body exam-state-body"><p><strong>{{ target?.description }}</strong></p><p>{{ target?.annulled ? "El registro volvera a estar disponible." : "El registro permanecera visible en el catalogo, pero no estara disponible en nuevos procesos." }}</p><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{ errorMessage }}</div></section><footer class="dialog-footer"><button type="button" class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close"><BioNexusActionIcon action="cancel" />Cancelar</button><button type="submit" class="bio-nexus-action bio-nexus-action-primary" :disabled="saving||!target"><BioNexusActionIcon :action="target?.annulled?'activate':'deactivate'" />{{ target?.annulled ? "Activar" : "Inactivar" }}</button></footer></form></dialog></template><script setup>import{ref}from"vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";import BioNexusDialogCloseButton from"@/components/ui/BioNexusDialogCloseButton.vue";defineProps({saving:{type:Boolean,default:false}});const emit=defineEmits(["confirm"]),dialog=ref(null),target=ref(null),entityLabel=ref("registro"),errorMessage=ref("");function open(row,label="registro"){target.value=row;entityLabel.value=label;errorMessage.value="";dialog.value?.showModal()}function close(){if(dialog.value?.open)dialog.value.close()}function clearError(){errorMessage.value=""}function setError(v){errorMessage.value=String(v||"")}function confirm(){if(target.value)emit("confirm",target.value,entityLabel.value)}defineExpose({open,close,clearError,setError});</script><style scoped>.exam-state-dialog{width:min(520px,calc(100vw - 32px));padding:0;border:1px solid var(--bio-nexus-color-border-strong);border-radius:var(--bio-nexus-radius-md)}.exam-state-body{display:grid;gap:var(--bio-nexus-space-3)}</style>
